+                ChunkedToXContentHelper.startArray(COMPLETION),
+                ChunkedToXContentHelper.startObject(),
+                ChunkedToXContentHelper.field("delta", delta),
+                ChunkedToXContentHelper.endObject(),
+                ChunkedToXContentHelper.endArray(),
+                ChunkedToXContentHelper.endObject()
+            );
+        }
+
+        @Override
